import type { SessionConfig } from "../src/utils/session.ts";
import { beforeEach, describe, vi } from "vitest";
import {
  useSession,
  getSession,
  updateSession,
  clearSession,
  readBody,
  H3,
  HTTPError,
} from "../src/index.ts";
import { seal, unseal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";
import { describeMatrix } from "./_setup.ts";

vi.mock("../src/utils/internal/iron-crypto.ts", async (importOriginal) => {
  const original = await importOriginal<typeof import("../src/utils/internal/iron-crypto.ts")>();
  return { ...original, unseal: vi.fn(original.unseal) };
});

describeMatrix("session", (t, { it, expect }) => {
  let app: H3;

  let cookie = "";

  let sessionIdCtr = 0;
  const sessionConfig: SessionConfig = {
    name: "h3-test",
    password: "1234567123456712345671234567123456712345671234567",
    generateId: () => ++sessionIdCtr + "",
  };

  beforeEach(() => {
    app = new H3({});
    t.app.all("/", async (event) => {
      const session = await useSession(event, sessionConfig);
      if (event.req.method === "POST") {
        await session.update((await readBody(event)) as any);
      }
      return { session };
    });
    t.app.use(app.handler);
  });

  it("initiates session", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()).toHaveLength(1);
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("sets SameSite=Lax by default", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()[0]).toContain("SameSite=Lax");
  });

  it("allows overriding SameSite via config.cookie", async () => {
    t.app.get("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: "strict" },
      });
      return { session };
    });
    const strict = await t.fetch("/strict");
    expect(strict.headers.getSetCookie()[0]).toContain("SameSite=Strict");

    t.app.get("/none", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: false },
      });
      return { session };
    });
    const none = await t.fetch("/none");
    expect(none.headers.getSetCookie()[0]).not.toContain("SameSite");
  });

  it("gets same session back", async () => {
    const result = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("set session data", async () => {
    const result = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ foo: "bar" }),
    });
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });

    const result2 = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result2.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });
  });

  it("gets same session back (concurrent)", async () => {
    app.get("/concurrent", async (event) => {
      const sessions = await Promise.all(
        [1, 2, 3].map(() =>
          useSession(event, sessionConfig).then((s) => ({
            id: s.id,
            data: s.data,
          })),
        ),
      );
      return {
        sessions,
      };
    });
    const result = await t.fetch("/concurrent", {
      headers: { Cookie: cookie },
    });
    expect(await result.json()).toMatchObject({
      sessions: [1, 2, 3].map(() => ({ id: "1", data: { foo: "bar" } })),
    });
  });

  it("clearSession sets maxAge=0 to delete cookie", async () => {
    t.app.get("/clear", async (event) => {
      await clearSession(event, sessionConfig);
      return { cleared: true };
    });
    const res = await t.fetch("/clear", {
      headers: { Cookie: cookie },
    });
    const cookies = res.headers.getSetCookie();
    expect(cookies.length).toBeGreaterThanOrEqual(1);
    expect(cookies[0]).toContain("Max-Age=0");
  });

  it("unseals and reseals legacy sessions sealed with iterations: 1", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    const result = await t.fetch("/", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    expect(await result.json()).toMatchObject({
      session: { id: "legacy", data: { foo: "legacy" } },
    });

    // Legacy cookie is transparently resealed with the current default
    const setCookies = result.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    const resealed = decodeURIComponent(setCookies[0].match(/h3-test=([^;]+)/)![1]);
    expect(
      await unseal(resealed, sessionConfig.password, sealDefaults), // current iterations, no fallback
    ).toMatchObject({ id: "legacy", data: { foo: "legacy" } });
  });

  it("rejects legacy sessions with legacySealFallback: false", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    t.app.all("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        legacySealFallback: false,
      });
      return { session };
    });

    const result = await t.fetch("/strict", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    const body = await result.json();
    expect(body.session.id).not.toBe("legacy");
    expect(body.session.data).toEqual({});
  });

  describe("password rotation", () => {
    const A = "alpha-password-alpha-password-alpha-password";
    const A2 = "alpha2-password-alpha2-password-alpha2-pass";
    const B = "bravo-password-bravo-password-bravo-password";
    const legacyOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };

    let routeCtr = 0;
    const sealWith = (password: string, payload: object, opts: object = sealDefaults) =>
      seal(payload, password, opts as typeof sealDefaults);
    const payloadOf = (data: Record<string, unknown> = { foo: "bar" }) => ({
      id: "rotated",
      createdAt: Date.now(),
      data,
    });
    // Registers a route reading the session with `config` and returns its path
    const route = (config: SessionConfig) => {
      const path = `/rotation-${++routeCtr}`;
      t.app.all(path, async (event) => {
        const session = await getSession(event, config);
        if (event.req.method === "POST") {
          await updateSession(event, config, (await readBody(event)) as any);
        }
        return {
          id: session.id,
          createdAt: session.createdAt,
          data: session.data,
          symbols: [
            ...Object.getOwnPropertySymbols(session),
            ...Object.getOwnPropertySymbols(session.data),
          ].length,
        };
      });
      return path;
    };
    const base = { name: "h3-rot", generateId: () => "fresh" };
    const cookieOf = (sealed: string) => `h3-rot=${encodeURIComponent(sealed)}`;
    const cookieHeader = (res: Response) =>
      res.headers
        .getSetCookie()
        .map((c) => c.split(";")[0])
        .join("; ");
    const sealedFrom = (res: Response) =>
      decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-rot=([^;]+)/)![1]);
    const unsealCalls = () => vi.mocked(unseal).mock.calls.map((call) => call[1]);

    beforeEach(() => {
      vi.mocked(unseal).mockClear();
    });

    it("opens a cookie sealed with an extra password", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, { headers: { Cookie: cookieOf(await sealWith(A, payloadOf())) } });
      expect(await res.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
    });

    it("opens a session header sealed with an extra password", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, {
        headers: { "x-h3-rot-session": await sealWith(A, payloadOf()) },
      });
      expect(await res.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
    });

    it("opens a chunked cookie sealed with an extra password", async () => {
      const chunked = { ...base, cookie: { chunkMaxLength: 100 } };
      const writePath = route({ ...chunked, password: A });
      const big = "x".repeat(600);
      const written = await t.fetch(writePath, {
        method: "POST",
        body: JSON.stringify({ big }),
      });
      expect(written.headers.getSetCookie().length).toBeGreaterThan(2);
      const path = route({ ...chunked, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, { headers: { Cookie: cookieHeader(written) } });
      expect(await res.json()).toMatchObject({ data: { big } });
      expect(res.headers.getSetCookie().length).toBeGreaterThan(2);
    });

    it("tries extra passwords in order and stops at the first that opens", async () => {
      const A1 = A;
      const path = route({ ...base, password: B, extraUnsealPasswords: [A1, A2] });
      const second = await t.fetch(path, {
        headers: { Cookie: cookieOf(await sealWith(A2, payloadOf())) },
      });
      expect(await second.json()).toMatchObject({ id: "rotated" });
      expect(unsealCalls().slice(0, 3)).toEqual([B, A1, A2]);

      vi.mocked(unseal).mockClear();
      const first = await t.fetch(path, {
        headers: { Cookie: cookieOf(await sealWith(A1, payloadOf())) },
      });
      expect(await first.json()).toMatchObject({ id: "rotated" });
      expect(unsealCalls()).toEqual([B, A1]);
    });

    it("seals only with password", async () => {
      const config: SessionConfig = { ...base, password: B, extraUnsealPasswords: [A] };
      const path = route(config);
      const res = await t.fetch(path, {
        method: "POST",
        headers: { Cookie: cookieOf(await sealWith(A, payloadOf())) },
        body: JSON.stringify({ more: 1 }),
      });
      const sealed = sealedFrom(res);
      expect(await unseal(sealed, B, sealDefaults)).toMatchObject({ id: "rotated" });
      await expect(unseal(sealed, A, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("reseals a cookie opened by an extra password with password", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const created = Date.now() - 5000;
      const res = await t.fetch(path, {
        headers: {
          Cookie: cookieOf(await sealWith(A, { ...payloadOf(), createdAt: created })),
        },
      });
      const body = await res.json();
      expect(body).toMatchObject({ id: "rotated", createdAt: created, data: { foo: "bar" }, symbols: 0 });
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(await unseal(sealedFrom(res), B, sealDefaults)).toMatchObject({
        id: "rotated",
        createdAt: created,
        data: { foo: "bar" },
      });

      // The migrated cookie keeps working once the old password is gone
      for (const extra of [undefined, []]) {
        const next = route({ ...base, password: B, extraUnsealPasswords: extra });
        const again = await t.fetch(next, { headers: { Cookie: cookieHeader(res) } });
        expect(await again.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
        expect(again.headers.getSetCookie()).toHaveLength(0);
      }
    });

    it("does not reseal sessions read from the header", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, {
        headers: { "x-h3-rot-session": await sealWith(A, payloadOf()) },
      });
      expect(await res.json()).toMatchObject({ id: "rotated", symbols: 0 });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("does not reseal or try extras for a cookie sealed with password", async () => {
      for (const extra of [undefined, [], [A]]) {
        vi.mocked(unseal).mockClear();
        const path = route({ ...base, password: B, extraUnsealPasswords: extra });
        const res = await t.fetch(path, {
          headers: { Cookie: cookieOf(await sealWith(B, payloadOf())) },
        });
        expect(await res.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
        expect(res.headers.getSetCookie()).toHaveLength(0);
        expect(unsealCalls()).toEqual([B]);
