      password: "1234567123456712345671234567123456712345671234567",
    };

    it("does not persist a session that is only read", async () => {
      t.app.get("/peek", async (event) => {
        const session = await getSession(event, lazyConfig);
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/peek");
      expect(res.headers.getSetCookie()).toHaveLength(0);
      expect(await res.json()).toMatchObject({ data: {} });
    });

    it("persists on the first write after a read", async () => {
      t.app.get("/login", async (event) => {
        await getSession(event, lazyConfig);
        const session = await updateSession(event, lazyConfig, { user: "alice" });
        return { id: session.id, data: session.data };
      });

      const res = await t.fetch("/login");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(res.headers.getSetCookie()[0]).toContain("h3-lazy=");
      expect(await res.json()).toMatchObject({ data: { user: "alice" } });
    });

    it("seals once when updateSession creates the session", async () => {
      const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
      t.app.get("/seal-count", async (event) => {
        await updateSession(event, lazyConfig, { user: "alice" });
        return "ok";
      });

      deriveBits.mockClear();
      const res = await t.fetch("/seal-count");
      expect(res.headers.getSetCookie()).toHaveLength(1);
      // Two derivations (encryption + integrity) for a single seal
      expect(deriveBits).toHaveBeenCalledTimes(2);
      deriveBits.mockRestore();
    });

    it("useSession still force-inits after a bare getSession", async () => {
      t.app.get("/peek-then-use", async (event) => {
        await getSession(event, lazyConfig); // e.g. auth middleware peeking
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res = await t.fetch("/peek-then-use");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("useSession still force-inits when read concurrently", async () => {
      t.app.get("/concurrent", async (event) => {
        const [, session] = await Promise.all([
          getSession(event, lazyConfig),
          useSession(event, lazyConfig),
        ]);
        return { id: session.id };
      });

      const res = await t.fetch("/concurrent");
      expect(res.headers.getSetCookie()).toHaveLength(1);
    });

    it("keeps the session id stable across requests once persisted", async () => {
      t.app.get("/stable", async (event) => {
        const session = await useSession(event, lazyConfig);
        return { id: session.id };
      });

      const res1 = await t.fetch("/stable");
      const setCookie = res1.headers.getSetCookie()[0];
      const { id } = await res1.json();

      const res2 = await t.fetch("/stable", {
        headers: { Cookie: setCookie.split(";")[0] },
      });
      expect(await res2.json()).toMatchObject({ id });
    });
  });
});

import type { SessionConfig } from "../src/utils/session.ts";
import { beforeEach, describe, vi } from "vitest";
import {
  useSession,
  getSession,
  updateSession,
  clearSession,
  readBody,
  H3,
  HTTPError,
} from "../src/index.ts";
import { seal, unseal, defaults as sealDefaults } from "../src/utils/internal/iron-crypto.ts";
import { describeMatrix } from "./_setup.ts";

vi.mock("../src/utils/internal/iron-crypto.ts", async (importOriginal) => {
  const original = await importOriginal<typeof import("../src/utils/internal/iron-crypto.ts")>();
  return { ...original, unseal: vi.fn(original.unseal) };
});

describeMatrix("session", (t, { it, expect }) => {
  let app: H3;

  let cookie = "";

  let sessionIdCtr = 0;
  const sessionConfig: SessionConfig = {
    name: "h3-test",
    password: "1234567123456712345671234567123456712345671234567",
    generateId: () => ++sessionIdCtr + "",
  };

  beforeEach(() => {
    app = new H3({});
    t.app.all("/", async (event) => {
      const session = await useSession(event, sessionConfig);
      if (event.req.method === "POST") {
        await session.update((await readBody(event)) as any);
      }
      return { session };
    });
    t.app.use(app.handler);
  });

  it("initiates session", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()).toHaveLength(1);
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("sets SameSite=Lax by default", async () => {
    const result = await t.fetch("/");
    expect(result.headers.getSetCookie()[0]).toContain("SameSite=Lax");
  });

  it("allows overriding SameSite via config.cookie", async () => {
    t.app.get("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: "strict" },
      });
      return { session };
    });
    const strict = await t.fetch("/strict");
    expect(strict.headers.getSetCookie()[0]).toContain("SameSite=Strict");

    t.app.get("/none", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        cookie: { sameSite: false },
      });
      return { session };
    });
    const none = await t.fetch("/none");
    expect(none.headers.getSetCookie()[0]).not.toContain("SameSite");
  });

  it("gets same session back", async () => {
    const result = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: {} },
    });
  });

  it("set session data", async () => {
    const result = await t.fetch("/", {
      method: "POST",
      headers: { Cookie: cookie },
      body: JSON.stringify({ foo: "bar" }),
    });
    cookie = result.headers.getSetCookie()[0];
    expect(await result.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });

    const result2 = await t.fetch("/", { headers: { Cookie: cookie } });
    expect(await result2.json()).toMatchObject({
      session: { id: "1", data: { foo: "bar" } },
    });
  });

  it("gets same session back (concurrent)", async () => {
    app.get("/concurrent", async (event) => {
      const sessions = await Promise.all(
        [1, 2, 3].map(() =>
          useSession(event, sessionConfig).then((s) => ({
            id: s.id,
            data: s.data,
          })),
        ),
      );
      return {
        sessions,
      };
    });
    const result = await t.fetch("/concurrent", {
      headers: { Cookie: cookie },
    });
    expect(await result.json()).toMatchObject({
      sessions: [1, 2, 3].map(() => ({ id: "1", data: { foo: "bar" } })),
    });
  });

  it("clearSession sets maxAge=0 to delete cookie", async () => {
    t.app.get("/clear", async (event) => {
      await clearSession(event, sessionConfig);
      return { cleared: true };
    });
    const res = await t.fetch("/clear", {
      headers: { Cookie: cookie },
    });
    const cookies = res.headers.getSetCookie();
    expect(cookies.length).toBeGreaterThanOrEqual(1);
    expect(cookies[0]).toContain("Max-Age=0");
  });

  it("unseals and reseals legacy sessions sealed with iterations: 1", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    const result = await t.fetch("/", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    expect(await result.json()).toMatchObject({
      session: { id: "legacy", data: { foo: "legacy" } },
    });

    // Legacy cookie is transparently resealed with the current default
    const setCookies = result.headers.getSetCookie();
    expect(setCookies).toHaveLength(1);
    const resealed = decodeURIComponent(setCookies[0].match(/h3-test=([^;]+)/)![1]);
    expect(
      await unseal(resealed, sessionConfig.password, sealDefaults), // current iterations, no fallback
    ).toMatchObject({ id: "legacy", data: { foo: "legacy" } });
  });

  it("rejects legacy sessions with legacySealFallback: false", async () => {
    const legacySealed = await seal(
      { id: "legacy", createdAt: Date.now(), data: { foo: "legacy" } },
      sessionConfig.password,
      {
        ...sealDefaults,
        encryption: { ...sealDefaults.encryption, iterations: 1 },
        integrity: { ...sealDefaults.integrity, iterations: 1 },
      },
    );

    t.app.all("/strict", async (event) => {
      const session = await useSession(event, {
        ...sessionConfig,
        legacySealFallback: false,
      });
      return { session };
    });

    const result = await t.fetch("/strict", {
      headers: { Cookie: `h3-test=${legacySealed}` },
    });
    const body = await result.json();
    expect(body.session.id).not.toBe("legacy");
    expect(body.session.data).toEqual({});
  });

  describe("password rotation", () => {
    const A = "alpha-password-alpha-password-alpha-password";
    const A2 = "alpha2-password-alpha2-password-alpha2-pass";
    const B = "bravo-password-bravo-password-bravo-password";
    const legacyOptions = {
      ...sealDefaults,
      encryption: { ...sealDefaults.encryption, iterations: 1 },
      integrity: { ...sealDefaults.integrity, iterations: 1 },
    };

    let routeCtr = 0;
    const sealWith = (password: string, payload: object, opts: object = sealDefaults) =>
      seal(payload, password, opts as typeof sealDefaults);
    const payloadOf = (data: Record<string, unknown> = { foo: "bar" }) => ({
      id: "rotated",
      createdAt: Date.now(),
      data,
    });
    // Registers a route reading the session with `config` and returns its path
    const route = (config: SessionConfig) => {
      const path = `/rotation-${++routeCtr}`;
      t.app.all(path, async (event) => {
        const session = await getSession(event, config);
        if (event.req.method === "POST") {
          await updateSession(event, config, (await readBody(event)) as any);
        }
        return {
          id: session.id,
          createdAt: session.createdAt,
          data: session.data,
          symbols: [
            ...Object.getOwnPropertySymbols(session),
            ...Object.getOwnPropertySymbols(session.data),
          ].length,
        };
      });
      return path;
    };
    const base = { name: "h3-rot", generateId: () => "fresh" };
    const cookieOf = (sealed: string) => `h3-rot=${encodeURIComponent(sealed)}`;
    const cookieHeader = (res: Response) =>
      res.headers
        .getSetCookie()
        .map((c) => c.split(";")[0])
        .join("; ");
    const sealedFrom = (res: Response) =>
      decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-rot=([^;]+)/)![1]);
    // One entry per password tried (each may also retry with the legacy iteration count)
    const unsealCalls = () =>
      vi
        .mocked(unseal)
        .mock.calls.map((call) => call[1])
        .filter((password, i, all) => password !== all[i - 1]);

    beforeEach(() => {
      vi.mocked(unseal).mockClear();
    });

    it("opens a cookie sealed with an extra password", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, { headers: { Cookie: cookieOf(await sealWith(A, payloadOf())) } });
      expect(await res.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
    });

    it("opens a session header sealed with an extra password", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, {
        headers: { "x-h3-rot-session": await sealWith(A, payloadOf()) },
      });
      expect(await res.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
    });

    it("opens a chunked cookie sealed with an extra password", async () => {
      const chunked = { ...base, cookie: { chunkMaxLength: 100 } };
      const writePath = route({ ...chunked, password: A });
      const big = "x".repeat(600);
      const written = await t.fetch(writePath, {
        method: "POST",
        body: JSON.stringify({ big }),
      });
      expect(written.headers.getSetCookie().length).toBeGreaterThan(2);
      const path = route({ ...chunked, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, { headers: { Cookie: cookieHeader(written) } });
      expect(await res.json()).toMatchObject({ data: { big } });
      expect(res.headers.getSetCookie().length).toBeGreaterThan(2);
    });

    it("tries extra passwords in order and stops at the first that opens", async () => {
      const A1 = A;
      const path = route({ ...base, password: B, extraUnsealPasswords: [A1, A2] });
      const second = await t.fetch(path, {
        headers: { Cookie: cookieOf(await sealWith(A2, payloadOf())) },
      });
      expect(await second.json()).toMatchObject({ id: "rotated" });
      expect(unsealCalls().slice(0, 3)).toEqual([B, A1, A2]);

      vi.mocked(unseal).mockClear();
      const first = await t.fetch(path, {
        headers: { Cookie: cookieOf(await sealWith(A1, payloadOf())) },
      });
      expect(await first.json()).toMatchObject({ id: "rotated" });
      expect(unsealCalls()).toEqual([B, A1]);
    });

    it("seals only with password", async () => {
      const config: SessionConfig = { ...base, password: B, extraUnsealPasswords: [A] };
      const path = route(config);
      const res = await t.fetch(path, {
        method: "POST",
        headers: { Cookie: cookieOf(await sealWith(A, payloadOf())) },
        body: JSON.stringify({ more: 1 }),
      });
      const sealed = sealedFrom(res);
      expect(await unseal(sealed, B, sealDefaults)).toMatchObject({ id: "rotated" });
      await expect(unseal(sealed, A, sealDefaults)).rejects.toThrow("Bad hmac value");
    });

    it("reseals a cookie opened by an extra password with password", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const created = Date.now() - 5000;
      const res = await t.fetch(path, {
        headers: {
          Cookie: cookieOf(await sealWith(A, { ...payloadOf(), createdAt: created })),
        },
      });
      const body = await res.json();
      expect(body).toMatchObject({ id: "rotated", createdAt: created, data: { foo: "bar" }, symbols: 0 });
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(await unseal(sealedFrom(res), B, sealDefaults)).toMatchObject({
        id: "rotated",
        createdAt: created,
        data: { foo: "bar" },
      });

      // The migrated cookie keeps working once the old password is gone
      for (const extra of [undefined, []]) {
        const next = route({ ...base, password: B, extraUnsealPasswords: extra });
        const again = await t.fetch(next, { headers: { Cookie: cookieHeader(res) } });
        expect(await again.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
        expect(again.headers.getSetCookie()).toHaveLength(0);
      }
    });

    it("does not reseal sessions read from the header", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const res = await t.fetch(path, {
        headers: { "x-h3-rot-session": await sealWith(A, payloadOf()) },
      });
      expect(await res.json()).toMatchObject({ id: "rotated", symbols: 0 });
      expect(res.headers.getSetCookie()).toHaveLength(0);
    });

    it("does not reseal or try extras for a cookie sealed with password", async () => {
      for (const extra of [undefined, [], [A]]) {
        vi.mocked(unseal).mockClear();
        const path = route({ ...base, password: B, extraUnsealPasswords: extra });
        const res = await t.fetch(path, {
          headers: { Cookie: cookieOf(await sealWith(B, payloadOf())) },
        });
        expect(await res.json()).toMatchObject({ id: "rotated", data: { foo: "bar" } });
        expect(res.headers.getSetCookie()).toHaveLength(0);
        expect(unsealCalls()).toEqual([B]);
      }
    });

    it("ignores sessions sealed with an unconfigured password", async () => {
      for (const extra of [undefined, [], [A2]]) {
        const path = route({ ...base, password: B, extraUnsealPasswords: extra });
        const sealed = await sealWith(A, payloadOf());
        for (const headers of [{ Cookie: cookieOf(sealed) }, { "x-h3-rot-session": sealed }]) {
          const res = await t.fetch(path, { headers });
          expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
        }
      }
    });

    it("still expires sessions opened by an extra password", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        const sealed = await sealWith(A, { id: "rotated", createdAt: t0, lastSeenAt: t0, data: {} });
        for (const limit of [{ maxAge: 60 }, { idleTimeout: 60 }]) {
          const path = route({ ...base, ...limit, password: B, extraUnsealPasswords: [A] });
          const fresh = await t.fetch(path, { headers: { Cookie: cookieOf(sealed) } });
          expect(await fresh.json()).toMatchObject({ id: "rotated" });
          vi.setSystemTime(t0 + 120_000);
          const stale = await t.fetch(path, { headers: { Cookie: cookieOf(sealed) } });
          expect(await stale.json()).toMatchObject({ id: "fresh" });
          vi.setSystemTime(t0);
        }
      } finally {
        vi.useRealTimers();
      }
    });

    it("rejects tampered seals", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      for (const password of [A, B]) {
        const parts = (await sealWith(password, payloadOf())).split("*");
        const last = parts.length - 1;
        parts[last] = (parts[last][0] === "A" ? "B" : "A") + parts[last].slice(1);
        const res = await t.fetch(path, { headers: { Cookie: cookieOf(parts.join("*")) } });
        expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
      }
    });

    it("rejects an expired seal without trying extra passwords", async () => {
      const t0 = Date.parse("2030-01-01T00:00:00Z");
      vi.useFakeTimers({ toFake: ["Date"], now: t0 });
      try {
        const sealed = await sealWith(A, payloadOf(), { ...sealDefaults, ttl: 1000 });
        vi.setSystemTime(t0 + 3_600_000);
        const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
        const res = await t.fetch(path, { headers: { Cookie: cookieOf(sealed) } });
        expect(await res.json()).toMatchObject({ id: "fresh" });
        expect(unsealCalls()).toEqual([B]);
      } finally {
        vi.useRealTimers();
      }
    });

    it("unseals legacy sessions sealed with an extra password and reseals them", async () => {
      const path = route({ ...base, password: B, extraUnsealPasswords: [A] });
      const sealed = await sealWith(A, payloadOf(), legacyOptions);
      const res = await t.fetch(path, { headers: { Cookie: cookieOf(sealed) } });
      expect(await res.json()).toMatchObject({ id: "rotated", data: { foo: "bar" }, symbols: 0 });
      expect(res.headers.getSetCookie()).toHaveLength(1);
      expect(await unseal(sealedFrom(res), B, sealDefaults)).toMatchObject({ id: "rotated" });
    });

    it("rejects legacy sessions sealed with an extra password when legacySealFallback is false", async () => {
      const path = route({
        ...base,
        password: B,
        extraUnsealPasswords: [A],
        legacySealFallback: false,
      });
      const sealed = await sealWith(A, payloadOf(), legacyOptions);
      const res = await t.fetch(path, { headers: { Cookie: cookieOf(sealed) } });
      expect(await res.json()).toMatchObject({ id: "fresh", data: {} });
    });
  });

  it("idleTimeout slides expiration for active sessions", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idle",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `idle-${++idCtr}`,
      };
      t.app.get("/idle", async (event) => {
        const session = await useSession(event, config);
        await session.update((data) => ({ hits: (data.hits || 0) + 1 }));
        return { id: session.id, data: session.data };
      });
      const idleCookie = (res: Response) =>
        res.headers.getSetCookie().find((c) => c.startsWith("h3-idle="));

      // t=0: new session
      const res1 = await t.fetch("/idle");
      expect((await res1.json()).id).toBe("idle-1");
      let cookie = idleCookie(res1)!;

      // t=45s: active request keeps the session and slides the cookie expiry
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/idle", { headers: { Cookie: cookie } });
      expect(await res2.json()).toMatchObject({ id: "idle-1", data: { hits: 2 } });
      const resealed = idleCookie(res2);
      expect(resealed).toBeDefined();
      expect(resealed).toContain(`Expires=${new Date(t0 + 45_000 + 60_000).toUTCString()}`);
      cookie = resealed!;

      // t=90s: past createdAt + idleTimeout, but only 45s idle — the session and
      // its data survive the reseals
      vi.setSystemTime(t0 + 90_000);
      const res3 = await t.fetch("/idle", { headers: { Cookie: cookie } });
      expect(await res3.json()).toMatchObject({ id: "idle-1", data: { hits: 3 } });
    } finally {
      vi.useRealTimers();
    }
  });

  it("idleTimeout expires sessions after exactly idleTimeout of inactivity", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-idle-exp",
        password: sessionConfig.password,
        idleTimeout: 60,
        generateId: () => `exp-${++idCtr}`,
      };
      t.app.get("/idle-expiry", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });

      const res1 = await t.fetch("/idle-expiry");
      expect((await res1.json()).id).toBe("exp-1");
      const cookie = res1.headers.getSetCookie().find((c) => c.startsWith("h3-idle-exp="))!;

      // No clock-skew slack: still alive at 59s of inactivity
      vi.setSystemTime(t0 + 59_000);
      const res2 = await t.fetch("/idle-expiry", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("exp-1");

      // ...and reset at 61s, measured from the original cookie's reseal time
      vi.setSystemTime(t0 + 61_000);
      const res3 = await t.fetch("/idle-expiry", { headers: { Cookie: cookie } });
      expect((await res3.json()).id).toBe("exp-2");
    } finally {
      vi.useRealTimers();
    }
  });

  it("maxAge caps a sliding session", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      let idCtr = 0;
      const config: SessionConfig = {
        name: "h3-both",
        password: sessionConfig.password,
        maxAge: 120,
        idleTimeout: 60,
        generateId: () => `both-${++idCtr}`,
      };
      t.app.get("/both", async (event) => {
        const session = await useSession(event, config);
        return { id: session.id };
      });
      const bothCookie = (res: Response) =>
        res.headers.getSetCookie().find((c) => c.startsWith("h3-both="))!;

      const res1 = await t.fetch("/both");
      expect((await res1.json()).id).toBe("both-1");
      let cookie = bothCookie(res1);

      // t=45s: idle window (t+60s) runs out before the absolute cap (t0+120s)
      vi.setSystemTime(t0 + 45_000);
      const res2 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res2.json()).id).toBe("both-1");
      cookie = bothCookie(res2);
      expect(cookie).toContain(`Expires=${new Date(t0 + 105_000).toUTCString()}`);

      // t=90s: now the absolute cap is the earlier of the two, so it wins
      vi.setSystemTime(t0 + 90_000);
      const res3 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res3.json()).id).toBe("both-1");
      cookie = bothCookie(res3);
      expect(cookie).toContain(`Expires=${new Date(t0 + 120_000).toUTCString()}`);

      // t=121s: only 31s idle, but past createdAt + maxAge — session resets
      vi.setSystemTime(t0 + 121_000);
      const res4 = await t.fetch("/both", { headers: { Cookie: cookie } });
      expect((await res4.json()).id).toBe("both-2");
